  const FACTION_UNIT_IDS = { vanguard: [], dominion: [], specter: [] };

  function createFactionUnit(factionId, name, archetypeIndex, variant) {
    const tuning = FACTION_UNIT_TUNING[factionId];
    const archetype = UNIT_ARCHETYPES[archetypeIndex];
    const base = archetype.stats;
    const id = `${tuning.prefix}_${archetype.key}${variant.key === 'standard' ? '' : `_${variant.key}`}`;
    const localCurve = 0.965 + (((archetypeIndex * 11) + tuning.prefix.charCodeAt(0)) % 8) * 0.01;
    const weapon = base.weapon ? {
      ...base.weapon,
      damage: Math.round(base.weapon.damage * tuning.damage * localCurve * variant.damage * 100) / 100,
      range: Math.round(base.weapon.range * tuning.range * (1.01 - (archetypeIndex % 3) * 0.004) * variant.range),
      reload: Math.max(0.18, base.weapon.reload * (2.01 - localCurve) * variant.reload),
      projectileSpeed: Math.round((base.weapon.projectileSpeed || 650) * (variant.key === 'precision' ? 1.08 : variant.key === 'recon' ? 1.05 : 1)),
      targets: [...base.weapon.targets],
      bonus: { ...(base.weapon.bonus || {}) }
    } : null;

    if (weapon?.splash) weapon.splash = Math.max(6, Math.round(weapon.splash * variant.splash));
    if (weapon?.minRange) weapon.minRange = Math.round(weapon.minRange * (variant.key === 'precision' ? 1.18 : variant.key === 'assault' ? 0.72 : 1));
    if (weapon && variant.key === 'assault') {
      weapon.bonus.infantry = (weapon.bonus.infantry || 1) * 1.08;
      weapon.bonus.vehicle = (weapon.bonus.vehicle || 1) * 1.06;
    }
    if (weapon && variant.key === 'precision') {
      weapon.bonus.building = (weapon.bonus.building || 1) * 1.26;
      weapon.ballistic = weapon.ballistic || (!base.infantry && !base.air && weapon.range >= 400);
    }

    const tierRequirement = archetype.tier === 1 ? [] : archetype.tier === 2 ? ['techLab'] : ['quantumLab'];
    const variantRequirement = variant.key === 'recon' && archetype.tier === 1
      ? ['radar']
      : variant.key === 'precision' && archetype.tier === 1
        ? ['techLab']
        : [];
    const detector = base.detector
      ? Math.round(base.detector * variant.vision)
      : variant.key === 'recon'
        ? 180 + archetype.tier * 70
        : undefined;

    UNIT_TYPES[id] = {
      ...base,
      id,
      name: `${name}${variant.suffix}`,
      icon: archetype.icon,
      role: `${archetype.role}. ${variant.scenario} ${tuning.doctrine}`,
      faction: factionId,
      tier: archetype.tier,
      archetypeIndex,
      variant: variant.key,
      variantLabel: variant.label,
      cost: Math.round(base.cost * tuning.cost * (0.98 + (archetypeIndex % 5) * 0.008) * variant.cost),
      time: base.time * (0.98 + (archetypeIndex % 4) * 0.012) * variant.time,
      hp: Math.round(base.hp * tuning.hp * localCurve * variant.hp),
      speed: base.speed * tuning.speed * (1.01 - (archetypeIndex % 4) * 0.004) * variant.speed,
      vision: Math.round(base.vision * variant.vision),
      detector,
      damageReduction: Math.min(0.34, (base.damageReduction || 0) + variant.damageReduction),
      healRate: base.healRate ? Math.round(base.healRate * variant.healRate) : base.healRate,
      healRange: base.healRange ? Math.round(base.healRange * variant.healRange) : base.healRange,
      stealth: Boolean(base.stealth || (variant.key === 'recon' && (base.infantry || base.air))),
      requires: [...new Set([...tierRequirement, ...variantRequirement])],
      rank: archetype.tier === 3 ? 3 : archetype.tier === 2 || variant.key === 'precision' ? 2 : 1,
      weapon
    };
    FACTION_UNIT_IDS[factionId].push(id);
  }

  // Сначала добавляются штатные модификации: это сохраняет стабильные индексы базового каталога.
  for (const [factionId, names] of Object.entries(FACTION_UNIT_NAMES)) {
    names.forEach((name, index) => createFactionUnit(factionId, name, index, UNIT_VARIANTS[0]));
  }
  // Затем добавляются три специализированные модификации каждого архетипа.
  for (const variant of UNIT_VARIANTS.slice(1)) {
    for (const [factionId, names] of Object.entries(FACTION_UNIT_NAMES)) {
      names.forEach((name, index) => createFactionUnit(factionId, name, index, variant));
    }
  }

  // v7.2: стратегическое вооружение существует только как боекомплект реальных носителей.
