    const ls = vx * vx + vy * vy;
    if (ls < 1e-6) return Math.hypot(px - ax, py - ay);
    const t = clamp78(((px - ax) * vx + (py - ay) * vy) / ls, 0, 1);
    return Math.hypot(px - (ax + vx * t), py - (ay + vy * t));
