    const drag = this._v78OrderDrag;
    if (!drag || !canvas) return;
    const g = canvas.getContext('2d');
    const dpr = this.viewport?.dpr || 1;
    g.save(); g.setTransform(dpr, 0, 0, dpr, 0, 0);
    const a = this.worldToScreen(drag.x, drag.y, 0);
