  // -------------------------------------------------------------------------
  // Aerodynamic silhouettes: curved fuselage, swept wings and canopy.
  // -------------------------------------------------------------------------
  const v79BaseDrawAir = Game.prototype.drawAirUnit3D;
  Game.prototype.drawAirUnit3D = function(unit) {
    v79BaseDrawAir.call(this,unit);
    if(!unit?.alive || this.camera.zoom<0.24) return;
    const role=this.unitVisualRole(unit), palette=this.getVisualPalette(this.displayedTeamForUnit(unit,'player'));
    const x=unit.renderX??unit.x,y=unit.renderY??unit.y,rot=unit.renderRotation??unit.rotation,r=unit.radius*(unit.stats.visualScale||1);
    const serviceLanded=unit.airServiceState==='servicing', serviceRolling=unit.airServiceState==='launch';
    const flightAltitude=this.getAircraftFlightAltitude119?.(unit)??(serviceLanded?r*.72:serviceRolling?r*2.35:r*5.2);
    const z=flightAltitude+(!serviceLanded&&!serviceRolling?Math.sin(this.time*2.6+hashString(unit.id))*r*.08:0);
    const f={x:Math.cos(rot),y:Math.sin(rot)},s={x:-f.y,y:f.x},p=(a,c,zz=z)=>({x:x+f.x*a+s.x*c,y:y+f.y*a+s.y*c,z:zz});
    const rotary=role==='lightGunship'||/helicopter/i.test(unit.typeId)||unit.typeId==='transportHelicopter';
    ctx.save();ctx.globalAlpha=.94;
    if(rotary){
      const c=v79Project(this,p(.12*r,0,z+r*.22)), ang=v79ScreenAngle(this,x,y,z,rot);
      const g=ctx.createLinearGradient(c.x-r*this.camera.zoom,c.y-r*this.camera.zoom*.4,c.x+r*this.camera.zoom,c.y+r*this.camera.zoom*.4);g.addColorStop(0,palette.armorLight);g.addColorStop(1,palette.armorDark);
      ctx.fillStyle=g;ctx.strokeStyle='rgba(10,14,12,.76)';ctx.lineWidth=Math.max(1,this.camera.zoom);
      ctx.beginPath();ctx.ellipse(c.x,c.y,Math.max(7,r*this.camera.zoom*.92),Math.max(4,r*this.camera.zoom*.43),ang,0,TWO_PI);ctx.fill();ctx.stroke();
      const tail=v79Project(this,p(-r*1.55,0,z+r*.20));ctx.strokeStyle=palette.armorDark;ctx.lineWidth=Math.max(3,r*this.camera.zoom*.20);ctx.lineCap='round';ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.lineTo(tail.x,tail.y);ctx.stroke();
      const glass=v79Project(this,p(r*.68,0,z+r*.35));ctx.fillStyle=alphaColor(palette.glass,.90);ctx.beginPath();ctx.ellipse(glass.x,glass.y,Math.max(3,r*this.camera.zoom*.27),Math.max(2,r*this.camera.zoom*.16),ang,0,TWO_PI);ctx.fill();
    } else {
      const span=role==='awacs'?2.25:role==='heavyBomber'?1.95:1.70;
      const len=role==='awacs'?1.95:role==='heavyBomber'?1.90:1.72;
      const outline=[p(r*len,0,z+r*.18),p(r*.38,r*span,z+r*.03),p(-r*.30,r*.72,z+r*.02),p(-r*1.44,r*.50,z+r*.05),p(-r*1.62,0,z+r*.18),p(-r*1.44,-r*.50,z+r*.05),p(-r*.30,-r*.72,z+r*.02),p(r*.38,-r*span,z+r*.03)].map(q=>v79Project(this,q));
      const front=v79Project(this,p(r*len,0,z+r*.2)), back=v79Project(this,p(-r*1.55,0,z+r*.1));
      const g=v79ScreenGradient(front,back,shadeColor(palette.armorLight,.12),shadeColor(palette.armor,-.18));
      v79FillSmooth(outline,g,'rgba(10,14,12,.78)',Math.max(1,this.camera.zoom));
      // Curved fuselage spine and canopy.
      const spine=[p(r*1.45,0,z+r*.30),p(r*.72,0,z+r*.48),p(-r*.15,0,z+r*.44),p(-r*1.28,0,z+r*.23)].map(q=>v79Project(this,q));
      ctx.strokeStyle=alphaColor(palette.armorLight,.58);ctx.lineWidth=Math.max(2,r*this.camera.zoom*.11);ctx.lineCap='round';v79SmoothPath(spine,false);ctx.stroke();
      const canopy=v79Project(this,p(r*.67,0,z+r*.48)), ang=v79ScreenAngle(this,x,y,z,rot);
      ctx.fillStyle=alphaColor(palette.glass,.88);ctx.strokeStyle=alphaColor('#d9ecea',.28);ctx.lineWidth=Math.max(.7,this.camera.zoom*.65);ctx.beginPath();ctx.ellipse(canopy.x,canopy.y,Math.max(3,r*this.camera.zoom*.27),Math.max(2,r*this.camera.zoom*.14),ang,0,TWO_PI);ctx.fill();ctx.stroke();
    }
    ctx.restore();
  };

  // Infantry already has articulated limbs in v7.8. Add subtle soft-shaded helmet/shoulder
  // forms so soldiers read as people at medium zoom without increasing their hitbox.
  const v79BaseDrawInfantry = Game.prototype.drawInfantryUnit3D;
