    const f={x:Math.cos(rot),y:Math.sin(rot)};const z=r*3.0;const head=this.worldToScreen(x+f.x*r*.05,y+f.y*r*.05,z);
    const rr=Math.max(2.1,r*this.camera.zoom*.23);const g=ctx.createRadialGradient(head.x-rr*.35,head.y-rr*.35,rr*.2,head.x,head.y,rr);g.addColorStop(0,shadeColor(pal.armorLight,.18));g.addColorStop(1,shadeColor(pal.armorDark,-.06));
