    const desiredHeight = (rawY2 - rawY1) * visibleScale;
    const padX = Math.max(8, (desiredWidth - (rawX2 - rawX1)) * .5);
    const padY = Math.max(8, (desiredHeight - (rawY2 - rawY1)) * .5);
