        await new Promise((resolve) => setTimeout(resolve, 4000));
        panel.dataset.state = 'sampling';
        panel.textContent = `COMBAT-STRESS: ${result.units.toLocaleString('ru-RU')} юнитов · инструментальный замер 8 с…`;
        let frames = 0;
