Unit.prototype.serialize=function(){const data=baseUnitSerialize160.call(this);ensureUnitState(this);data.suppression160=this.suppression160;data.cohesion160=this.cohesion160;data.supply160=this.supply160;data.morale160=this.morale160;data.lastSuppressedAt160=this.lastSuppressedAt160;data.functionalDamage160={...this.functionalDamage160};data.v160Retreating=!!this._v160Retreating;return data;};
const baseHydrate=Game.prototype.hydrate;
Game.prototype.hydrate=function(data){this.__pendingOperationalCore160=data?.operationalCore160||null;const result=baseHydrate.call(this,data);const savedUnits=new Map(safeArray(data?.entities).filter(e=>e.kind==='unit').map(e=>[e.id,e]));for(const u of this.units||[]){const d=savedUnits.get(u.id);if(d){for(const k of ['suppression160','cohesion160','supply160','morale160','lastSuppressedAt160'])if(Number.isFinite(d[k]))u[k]=d[k];}if(d.functionalDamage160)u.functionalDamage160={...d.functionalDamage160};u._v160Retreating=!!d.v160Retreating;ensureUnitState(u);}ensureCore(this);delete this.__pendingOperationalCore160;return result;};
const baseSave=Game.prototype.save;
Game.prototype.save=function(notify=true){const ok=baseSave.call(this,notify);if(!ok)return ok;try{const raw=D.storageGet(D.SAVE_KEY);const data=raw?JSON.parse(raw):null;if(data){data.operationalCore160=ensureCore(this).serialize();data.operationalSchemaVersion=3;D.storageSet(D.SAVE_KEY,JSON.stringify(data));}}catch(e){console.warn('[v16] extension save failed',e);}return ok;};

// Export deterministic diagnostics/replay snapshot for automated verification and multiplayer debugging.
Game.prototype.operationalDiagnostics160=function(){const c=ensureCore(this);return {version:VERSION,build:BUILD,time:this.time,workerReady:c.workerReady,workerHash:c.workerHash,localHash:c.stateHash(),subsystemHashes:c.subsystemHashes(),canonicalTeams:{player:1,enemy:2,neutral:0},sectors:c.sectors.map(s=>({id:s.id,owner:s.owner,control:s.control,value:s.value})),contacts:c.contacts.size,operations:c.operations.map(o=>({id:o.id,state:o.state,target:o.targetSectorId,units:c.opUnits(o).length})),reserve:c.reserveIds.length,commandLog:c.commandLog.length,metrics:{...c.metrics}};};
Game.prototype.exportReplay160=function(){const c=ensureCore(this);return {version:VERSION,build:BUILD,seed:this.seed,difficulty:this.difficultyKey,commands:c.commandLog.slice(),finalHash:c.stateHash(),subsystemHashes:c.subsystemHashes(),time:this.time};};

// Operational information is rendered only on the minimap/UI; it never changes simulation detail from camera state.
const baseRenderMinimap160=Game.prototype.renderMinimap;
Game.prototype.renderMinimap=function(){
  const result=baseRenderMinimap160.call(this);const core=ensureCore(this),canvas=document.querySelector('#minimap');if(!canvas)return result;
  const c=canvas.getContext('2d'),sx=canvas.width/WORLD.width,sy=canvas.height/WORLD.height;c.save();
  for(const s of core.sectors){const alpha=Math.min(.12,.025+Math.abs(s.control)*.08);c.fillStyle=s.owner==='player'?`rgba(90,210,145,${alpha})`:s.owner==='enemy'?`rgba(230,92,78,${alpha})`:`rgba(220,210,150,${alpha*.45})`;c.fillRect(s.x0*sx,s.y0*sy,(s.x1-s.x0)*sx,(s.y1-s.y0)*sy);c.strokeStyle='rgba(220,240,229,.12)';c.strokeRect(s.x0*sx+.5,s.y0*sy+.5,(s.x1-s.x0)*sx-1,(s.y1-s.y0)*sy-1);}
  c.restore();return result;
};
const baseRenderSelection160=Game.prototype.renderSelectionUI;
Game.prototype.renderSelectionUI=function(){const result=baseRenderSelection160.call(this);const one=this.selected?.length===1?this.selected[0]:null;if(one?.kind==='unit'){ensureUnitState(one);const box=document.querySelector('#selection-details');if(box&&!box.querySelector('.v160-operational-state'))box.insertAdjacentHTML('beforeend',`<div class="v160-operational-state"><div class="stat-line"><span>Подавление</span><strong>${Math.round(one.suppression160*100)}%</strong></div><div class="stat-line"><span>Сплочённость</span><strong>${Math.round(one.cohesion160*100)}%</strong></div><div class="stat-line"><span>Снабжение</span><strong>${Math.round(one.supply160*100)}%</strong></div></div>`);}return result;};

// Minimal operational overlay toggle, deliberately lightweight and off by default.
window.__FD_V160__={VERSION,BUILD,COMMANDS,get core(){return D.game?ensureCore(D.game):null;},diagnostics(){return D.game?.operationalDiagnostics160?.()||null;},replay(){return D.game?.exportReplay160?.()||null;}};
const game=D.game;if(game)ensureCore(game);
const title=document.title;void 0;const eyebrow=document.querySelector('#start-screen .eyebrow');if(eyebrow)void 0;
console.info('[Frontline Dominion] Operational Core v16.0 build 170 loaded');
